const ownerOfObligation = (address, pageOfObligationMap) => {
  let current = address.replace(/\[\d+\]/g, '')
  while (current !== null) {
    if (pageOfObligationMap.has(current)) {
      return pageOfObligationMap.get(current)
    }
    current = ancestorTemplate(current)
  }
  return undefined
}

